data.minimal_example:
final controller = PaneController(
  entries: [
    PaneEntry(id: 'sidebar', initialSize: PaneSize.pixel(250)),
    PaneEntry(id: 'content', initialSize: PaneSize.fraction(1.0)),
  ],
);

MultiPane(
  direction: Axis.horizontal,
  controller: controller,
  paneBuilder: (context, id) => switch (id) {
    'sidebar' => Sidebar(),
    'content' => Content(),
    _ => const SizedBox(),
  },
)
